use std::{error::Error, fs};

use super::{f64_to_u64_exact, format_float_g, i64_to_f64, quote, to_lower, u64_to_f64};

type TestResult = Result<(), Box<dyn Error>>;

/// Replays `testdata/golden/float_g.txt`, generated by `testdata/go` from Go's
/// `strconv.FormatFloat(f, 'g', -1, 64)`.
#[test]
fn format_float_g_matches_go() -> TestResult {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/testdata/golden/float_g.txt");
    let table = fs::read_to_string(path)?;
    let mut checked = 0_usize;
    for line in table.lines() {
        let (bits, expected) = line.split_once(' ').ok_or("malformed float_g line")?;
        let value = f64::from_bits(u64::from_str_radix(bits, 16)?);
        ensure_eq!(format_float_g(value), expected, "formatting bits {bits}");
        checked += 1;
    }
    ensure!(checked > 2000, "the float table has {checked} entries");
    Ok(())
}

#[test]
fn u64_to_f64_rounds_like_go() -> TestResult {
    for text in [
        "0",
        "1",
        "4294967295",
        "4294967296",
        "9007199254740992",
        "9007199254740993",
        "9007199254740995",
        "123456789012345678",
        "18446744073709551615",
    ] {
        let integer: u64 = text.parse()?;
        let float: f64 = text.parse()?;
        ensure_eq!(
            u64_to_f64(integer).to_bits(),
            float.to_bits(),
            "converting {text}"
        );
    }
    ensure_eq!(
        i64_to_f64(i64::MIN).to_bits(),
        0xC3E0_0000_0000_0000,
        "MIN is -2^63"
    );
    ensure_eq!(i64_to_f64(-3).to_bits(), (-3.0_f64).to_bits(), "-3");
    Ok(())
}

#[test]
fn f64_to_u64_exact_accepts_only_whole_numbers() -> TestResult {
    ensure_eq!(f64_to_u64_exact(0.0), Some(0), "zero");
    ensure_eq!(f64_to_u64_exact(42.0), Some(42), "42");
    ensure_eq!(
        f64_to_u64_exact(9_007_199_254_740_992.0),
        Some(9_007_199_254_740_992),
        "2^53"
    );
    ensure_eq!(f64_to_u64_exact(1.844_674_407_370_955_2e19), None, "2^64");
    ensure_eq!(f64_to_u64_exact(0.5), None, "fraction");
    ensure_eq!(f64_to_u64_exact(-1.0), None, "negative");
    ensure_eq!(f64_to_u64_exact(f64::NAN), None, "NaN");
    ensure_eq!(f64_to_u64_exact(f64::INFINITY), None, "infinity");
    Ok(())
}

#[test]
fn to_lower_uses_simple_case_mapping() -> TestResult {
    ensure_eq!(to_lower("AppNexus"), "appnexus", "ascii");
    ensure_eq!(
        to_lower("\u{130}X"),
        "ix",
        "dotted capital I maps to i like unicode.ToLower"
    );
    ensure_eq!(
        to_lower("\u{3a3}\u{3a3}"),
        "\u{3c3}\u{3c3}",
        "no final sigma rule"
    );
    Ok(())
}

#[test]
fn quote_matches_go_for_ascii() -> TestResult {
    ensure_eq!(
        quote("a\"b\\c\nd\te\u{1}"),
        "\"a\\\"b\\\\c\\nd\\te\\x01\"",
        "escapes"
    );
    ensure_eq!(quote("\u{7f}"), "\"\\x7f\"", "DEL");
    ensure_eq!(quote("\u{85}"), "\"\\u0085\"", "C1 control");
    Ok(())
}
